CREATE TABLE IF NOT EXISTS public."chat_messages" (
  "id" text NOT NULL,
  "chat_wid" text NOT NULL,
  "conversation_record_id" uuid NOT NULL,
  "device_id" text NOT NULL,
  "flow" text NOT NULL,
  "kind" text NOT NULL,
  "body" text,
  "from_phone" text,
  "to_phone" text,
  "ack" text,
  "date" timestamp with time zone NOT NULL,
  "media_file_id" text,
  "media_mime" text,
  "media_size" integer,
  "media_caption" text,
  "reference" text,
  "quoted" jsonb,
  "meta" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at" timestamp with time zone NOT NULL DEFAULT now(),
  "subtype" text,
  "message_hash" text GENERATED ALWAYS AS (
CASE
    WHEN (id ~ '^(true|false)_[^_]+@[a-z.]+_'::text) THEN split_part(id, '_'::text, 3)
    ELSE NULL::text
END) STORED,
  "send_source" text,
  CONSTRAINT "chat_messages_flow_check" CHECK ((flow = ANY (ARRAY['in'::text, 'out'::text]))),
  CONSTRAINT "chat_messages_pkey" PRIMARY KEY (id)
);
