  CONSTRAINT "fin_product_versions_min_down_payment_pct_check" CHECK (((min_down_payment_pct IS NULL) OR ((min_down_payment_pct >= (0)::numeric) AND (min_down_payment_pct <= (100)::numeric)))),
  CONSTRAINT "fin_product_versions_min_employment_months_check" CHECK (((min_employment_months IS NULL) OR (min_employment_months >= 0))),
